// Default communications microphone, raw PCM stdout. It never writes audio to disk.
#include <windows.h>
#include <mmdeviceapi.h>
#include <audioclient.h>
#include <vector>
int wmain(int argc,wchar_t**argv){int seconds=4;if(argc==3&&!wcscmp(argv[1],L"--seconds"))seconds=_wtoi(argv[2]);if(seconds<1||seconds>20)return 2;CoInitializeEx(0,COINIT_MULTITHREADED);IMMDeviceEnumerator*e=0;IMMDevice*d=0;IAudioClient*a=0;IAudioCaptureClient*c=0;HRESULT h=CoCreateInstance(__uuidof(MMDeviceEnumerator),0,CLSCTX_ALL,IID_PPV_ARGS(&e));if(SUCCEEDED(h))h=e->GetDefaultAudioEndpoint(eCapture,eCommunications,&d);if(SUCCEEDED(h))h=d->Activate(__uuidof(IAudioClient),CLSCTX_ALL,0,(void**)&a);WAVEFORMATEX f{};f.wFormatTag=WAVE_FORMAT_PCM;f.nChannels=2;f.nSamplesPerSec=48000;f.wBitsPerSample=16;f.nBlockAlign=4;f.nAvgBytesPerSec=192000;if(SUCCEEDED(h))h=a->Initialize(AUDCLNT_SHAREMODE_SHARED,AUDCLNT_STREAMFLAGS_EVENTCALLBACK|AUDCLNT_STREAMFLAGS_AUTOCONVERTPCM,0,0,&f,0);if(SUCCEEDED(h))h=a->GetService(IID_PPV_ARGS(&c));HANDLE ev=CreateEventW(0,FALSE,FALSE,0);if(SUCCEEDED(h))h=a->SetEventHandle(ev);if(SUCCEEDED(h))h=a->Start();ULONGLONG end=GetTickCount64()+(ULONGLONG)seconds*1000;while(SUCCEEDED(h)&&GetTickCount64()<end){if(WaitForSingleObject(ev,100)!=WAIT_OBJECT_0)continue;UINT32 p=0;while(SUCCEEDED(c->GetNextPacketSize(&p))&&p){BYTE*x=0;UINT32 fr=0;DWORD fl=0;h=c->GetBuffer(&x,&fr,&fl,0,0);if(FAILED(h))break;size_t b=(size_t)fr*4;if(fl&AUDCLNT_BUFFERFLAGS_SILENT){std::vector<BYTE>z(b);fwrite(z.data(),1,b,stdout);}else fwrite(x,1,b,stdout);c->ReleaseBuffer(fr);p=0;}}if(a)a->Stop();if(ev)CloseHandle(ev);if(c)c->Release();if(a)a->Release();if(d)d->Release();if(e)e->Release();CoUninitialize();return FAILED(h)?1:0;}
